<script setup lang="ts">import { ref, onMounted, onUnmounted, watch } from 'vue';
import { useDataStore } from '@/stores/dataStore';
import { useViewStore } from '@/stores/viewStore';
import type { PlatformData, SpecialEvent } from '@/types';
import { CampType, SpecialEventType } from '@/types';
import PropertyBox from './PropertyBox.vue';
import ConnectingLine from './ConnectingLine.vue';
const dataStore = useDataStore();
const viewStore = useViewStore();
const canvasRef = ref<HTMLCanvasElement | null>(null);
const containerRef = ref<HTMLDivElement | null>(null);
const width = ref(800);
const height = ref(600);
const isDragging = ref(false);
const lastMousePos = ref({ x: 0, y: 0 });
const mousePos = ref({ x: 0, y: 0 });
const geoPos = ref({ lon: 0, lat: 0 });
const drawGrid = (ctx: CanvasRenderingContext2D) => {
 ctx.strokeStyle = 'rgba(100, 100, 150, 0.3)';
 ctx.lineWidth = 1;
 const gridStep = 0.1;
 const leftLon = viewStore.viewState.centerLon - (width.value / 2) * viewStore.viewState.scale / (width.value * 111320 * Math.cos(viewStore.viewState.centerLat * Math.PI / 180));
 const rightLon = viewStore.viewState.centerLon + (width.value / 2) * viewStore.viewState.scale / (width.value * 111320 * Math.cos(viewStore.viewState.centerLat * Math.PI / 180));
 const topLat = viewStore.viewState.centerLat + (height.value / 2) * viewStore.viewState.scale / (width.value * 111320);
 const bottomLat = viewStore.viewState.centerLat - (height.value / 2) * viewStore.viewState.scale / (width.value * 111320);
 const startLon = Math.floor(leftLon / gridStep) * gridStep;
 const endLon = Math.ceil(rightLon / gridStep) * gridStep;
 const startLat = Math.floor(bottomLat / gridStep) * gridStep;
 const endLat = Math.ceil(topLat / gridStep) * gridStep;
 for (let lon = startLon; lon <= endLon; lon += gridStep) {
 const { x } = viewStore.geoToScreen(lon, viewStore.viewState.centerLat, width.value, height.value);
 ctx.beginPath();
 ctx.moveTo(x, 0);
 ctx.lineTo(x, height.value);
 ctx.stroke();
 }
 for (let lat = startLat; lat <= endLat; lat += gridStep) {
 const { y } = viewStore.geoToScreen(viewStore.viewState.centerLon, lat, width.value, height.value);
 ctx.beginPath();
 ctx.moveTo(0, y);
 ctx.lineTo(width.value, y);
 ctx.stroke();
 }
};
const drawBackground = (ctx: CanvasRenderingContext2D) => {
 const gradient = ctx.createLinearGradient(0, 0, 0, height.value);
 gradient.addColorStop(0, '#1a1a2e');
 gradient.addColorStop(0.5, '#16213e');
 gradient.addColorStop(1, '#0f3460');
 ctx.fillStyle = gradient;
 ctx.fillRect(0, 0, width.value, height.value);
};
const getCampColor = (camp: CampType): string => {
 switch (camp) {
 case CampType.Friendly: return '#00ff00';
 case CampType.Enemy: return '#ff0000';
 case CampType.Neutral: return '#ffff00';
 default: return '#888888';
 }
};
const drawPlatform = (ctx: CanvasRenderingContext2D, platform: PlatformData) => {
 const { x, y } = viewStore.geoToScreen(platform.lon, platform.lat, width.value, height.value);
 if (x < -50 || x > width.value + 50 || y < -50 || y > height.value + 50)
 return;
 const isOwnShip = platform.id === 'SHIP_001';
 const color = getCampColor(platform.camp);
 ctx.save();
 ctx.translate(x, y);
 if (isOwnShip) {
 ctx.fillStyle = color;
 ctx.strokeStyle = color;
 ctx.lineWidth = 2;
 ctx.beginPath();
 ctx.moveTo(15, 0);
 ctx.lineTo(-10, -8);
 ctx.lineTo(-5, 0);
 ctx.lineTo(-10, 8);
 ctx.closePath();
 ctx.fill();
 ctx.stroke();
 }
 else {
 ctx.fillStyle = color;
 ctx.strokeStyle = color;
 ctx.lineWidth = 2;
 ctx.beginPath();
 ctx.arc(0, 0, 10, 0, Math.PI * 2);
 ctx.fill();
 ctx.stroke();
 }
 ctx.restore();
 ctx.fillStyle = '#ffffff';
 ctx.font = '12px Arial';
 ctx.fillText(platform.id, x + 18, y + 4);
};
const getEventIcon = (eventType: SpecialEventType): {
 icon: string;
 color: string;
} => {
 switch (eventType) {
 case SpecialEventType.Alert: return { icon: '!', color: '#ff0000' };
 case SpecialEventType.Attack: return { icon: 'A', color: '#8b0000' };
 case SpecialEventType.Defense: return { icon: 'D', color: '#0000ff' };
 case SpecialEventType.Contact: return { icon: 'C', color: '#00ffff' };
 case SpecialEventType.Damage: return { icon: 'X', color: '#ff8c00' };
 case SpecialEventType.MissionStart: return { icon: 'M', color: '#00ff00' };
 case SpecialEventType.MissionEnd: return { icon: 'E', color: '#808080' };
 case SpecialEventType.Lost: return { icon: '?', color: '#ff00ff' };
 case SpecialEventType.Repair: return { icon: 'R', color: '#90ee90' };
 default: return { icon: '*', color: '#ffff00' };
 }
};
const drawEventMarker = (ctx: CanvasRenderingContext2D, event: SpecialEvent) => {
 const platform = dataStore.getPlatformById(event.targetId);
 if (!platform)
 return;
 const { x, y } = viewStore.geoToScreen(platform.lon, platform.lat, width.value, height.value);
 if (x < -50 || x > width.value + 50 || y < -50 || y > height.value + 50)
 return;
 const { icon, color } = getEventIcon(event.eventType);
 ctx.save();
 ctx.translate(x + 25, y - 20);
 ctx.fillStyle = color;
 ctx.strokeStyle = color;
 ctx.lineWidth = 2;
 ctx.fillRect(-10, -10, 20, 20);
 ctx.fillStyle = '#ffffff';
 ctx.font = 'bold 14px Arial';
 ctx.textAlign = 'center';
 ctx.textBaseline = 'middle';
 ctx.fillText(icon, 0, 0);
 ctx.restore();
};
const draw = () => {
 const canvas = canvasRef.value;
 if (!canvas)
 return;
 const ctx = canvas.getContext('2d');
 if (!ctx)
 return;
 drawBackground(ctx);
 drawGrid(ctx);
 for (const platform of dataStore.validPlatforms) {
 drawPlatform(ctx, platform);
 }
 for (const event of dataStore.events) {
 drawEventMarker(ctx, event);
 }
};
let animationId: number;
const animate = () => {
 draw();
 animationId = requestAnimationFrame(animate);
};
const handleResize = () => {
 if (containerRef.value) {
 width.value = containerRef.value.clientWidth;
 height.value = containerRef.value.clientHeight;
 }
};
const handleMouseDown = (e: MouseEvent) => {
 isDragging.value = true;
 lastMousePos.value = { x: e.clientX, y: e.clientY };
};
const handleMouseMove = (e: MouseEvent) => {
 const rect = canvasRef.value?.getBoundingClientRect();
 if (rect) {
 mousePos.value = { x: e.clientX - rect.left, y: e.clientY - rect.top };
 const geo = viewStore.screenToGeo(mousePos.value.x, mousePos.value.y, width.value, height.value);
 geoPos.value = { lon: geo.lon, lat: geo.lat };
 }
 if (isDragging.value) {
 const dx = e.clientX - lastMousePos.value.x;
 const dy = e.clientY - lastMousePos.value.y;
 viewStore.pan(dx, dy, width.value);
 lastMousePos.value = { x: e.clientX, y: e.clientY };
 }
};
const handleMouseUp = () => {
 isDragging.value = false;
};
const handleWheel = (e: WheelEvent) => {
 e.preventDefault();
 if (e.deltaY < 0) {
 viewStore.zoomIn();
 }
 else {
 viewStore.zoomOut();
 }
};
const handleClick = (e: MouseEvent) => {
 if (isDragging.value)
 return;
 const rect = canvasRef.value?.getBoundingClientRect();
 if (!rect)
 return;
 const clickX = e.clientX - rect.left;
 const clickY = e.clientY - rect.top;
 for (const platform of dataStore.validPlatforms) {
 const { x, y } = viewStore.geoToScreen(platform.lon, platform.lat, width.value, height.value);
 const dx = clickX - x;
 const dy = clickY - y;
 if (dx * dx + dy * dy <= 225) {
 viewStore.createPropertyBox(platform.id, platform.name, platform.id === 'SHIP_001', platform.lon, platform.lat, platform.speed, x, y);
 return;
 }
 }
 viewStore.hideAllPropertyBoxes();
};
onMounted(() => {
 handleResize();
 window.addEventListener('resize', handleResize);
 animate();
});
onUnmounted(() => {
 window.removeEventListener('resize', handleResize);
 if (animationId) {
 cancelAnimationFrame(animationId);
 }
});
watch(() => dataStore.lastUpdateTime, () => {
 dataStore.validPlatforms.forEach(p => {
 viewStore.updatePropertyBoxData(p.id, p.lon, p.lat, p.speed);
 });
});
</script>

<template>
  <div ref="containerRef" class="map-container">
    <canvas
      ref="canvasRef"
      :width="width"
      :height="height"
      class="map-canvas"
      @mousedown="handleMouseDown"
      @mousemove="handleMouseMove"
      @mouseup="handleMouseUp"
      @mouseleave="handleMouseUp"
      @wheel="handleWheel"
      @click="handleClick"
    />
    
    <div class="mouse-position">
      <span>Lon: {{ geoPos.lon.toFixed(4) }}</span>
      <span>Lat: {{ geoPos.lat.toFixed(4) }}</span>
      <span>Scale: {{ (viewStore.viewState.scale / 1000).toFixed(0) }}m</span>
    </div>

    <ConnectingLine 
      v-for="box in viewStore.propertyBoxes" 
      :key="box.id" 
      :box="box"
      :width="width"
      :height="height"
    />

    <PropertyBox
      v-for="box in viewStore.propertyBoxes"
      :key="box.id"
      :box="box"
      :platform="dataStore.getPlatformById(box.id)"
    />
  </div>
</template>

<style scoped>
.map-container {
  position: relative;
  width: 100%;
  height: 100%;
  overflow: hidden;
}

.map-canvas {
  display: block;
  width: 100%;
  height: 100%;
  cursor: grab;
}

.map-canvas:active {
  cursor: grabbing;
}

.mouse-position {
  position: absolute;
  bottom: 10px;
  left: 10px;
  background: rgba(0, 0, 0, 0.7);
  color: white;
  padding: 8px 12px;
  border-radius: 4px;
  font-size: 12px;
  display: flex;
  gap: 15px;
}
</style>
