<script setup lang="ts">
import { computed } from 'vue'
import { useViewStore } from '@/stores/viewStore'
import type { PropertyBox as PropertyBoxType } from '@/types'

const props = defineProps<{
  box: PropertyBoxType
  width: number
  height: number
}>()

const viewStore = useViewStore()

const shipPosition = computed(() => {
  return viewStore.geoToScreen(props.box.lon, props.box.lat, props.width, props.height)
})

const boxCenter = computed(() => ({
  x: props.box.x + 100,
  y: props.box.y + 60
}))
</script>

<template>
  <svg class="connecting-line" :width="width" :height="height">
    <line
      :x1="shipPosition.x"
      :y1="shipPosition.y"
      :x2="boxCenter.x"
      :y2="boxCenter.y"
      stroke="white"
      stroke-width="2"
      stroke-dasharray="5,5"
    />
  </svg>
</template>

<style scoped>
.connecting-line {
  position: absolute;
  top: 0;
  left: 0;
  pointer-events: none;
  z-index: 50;
}
</style>
